window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[179]={"id":"179","numero":179,"titre":"Risques sanitaires liés à l'eau et à l'alimentation · TIAC","objectifs":[{"id":"179-1","rang":"B","rubrique":"Étiologies","titre":"Connaître les parasitoses transmises par la consommation d’eau","contenu":"<div class=\"notion-course\"><p><span>Les</span> parasitoses transmises par la <span>consommation d'eau</span> sont quasi exclusivement des <strong><span>protozooses</span></strong>, à transmission <span>féco-orale</span>. Quatre agents sont à connaître.</p>\n      <table>\n        <thead><tr><th>Parasitose</th><th>Agent &amp; réservoir</th><th>Clinique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Amoebose</span></strong></td>\n            <td><span>Entamoeba histolytica</span> ; protozoose à réservoir <strong>strictement humain</strong>, cosmopolite</td>\n            <td>Surtout dans <span>les</span> zones à <span>hygiène pauvre</span> ; amoebose intestinale</td>\n          </tr>\n          <tr>\n            <td><strong><span>Cryptosporidiose</span></strong></td>\n            <td><span>Cryptosporidium</span> ; protozoose cosmopolite ; transmission <span>féco-orale</span> ou <span>manu-portée</span></td>\n            <td><span>Diarrhée aiguë cholérigorme</span> ou <span>chronique</span> + <span>malabsorption</span> chez l'<span>immunodéprimé</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Giardiose</span></strong></td>\n            <td>Giardia intestinalis peut infecter l’humain et d’autres mammifères ; une transmission zoonotique est possible selon les assemblages. Eau, aliments et transmission féco-orale interhumaine sont à considérer.</td>\n            <td>Souvent <span>asymptomatique</span> ; possible <span>diarrhée chronique</span> de l'enfant → <span>malabsorption / malnutrition</span> (pays pauvres)</td>\n          </tr>\n          <tr>\n            <td><strong><span>Toxoplasmose</span></strong></td>\n            <td><span>Toxoplasma gondii</span> ; protozoose cosmopolite dont le <strong>chat est l'hôte définitif</strong></td>\n            <td>Symptomatique dans <span>≈ 20 %</span> des cas, tableau aspécifique (<span><span class=\"nc-red_bg\">fièvre</span></span>, <span>polyadénopathies</span>…)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 172 — Parasitose digestive · 175 — Voyage en pays tropical</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":0},{"id":"179-2","rang":"B","rubrique":"Étiologies","titre":"Connaître les parasitoses transmises par les aliments","contenu":"<div class=\"notion-course\"><p><span>Les</span> parasitoses d'origine <span>alimentaire</span> sont surtout des <strong><span>helminthoses</span></strong>, acquises en ingérant viande ou poisson <span>crus ou insuffisamment cuits</span>.</p>\n      <table>\n        <thead><tr><th>Parasitose</th><th>Mode de contamination</th><th>Clinique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Taeniasis</span></strong></td>\n            <td>Ingestion de viande parasitée (bœuf, porc)</td>\n            <td>Téniasis intestinal — <em>détaillé à l'item 172</em></td>\n          </tr>\n          <tr>\n            <td><strong><span>Trichinellose</span></strong></td>\n            <td>Zoonose cosmopolite ; l'homme est un <strong>hôte accidentel</strong> en mangeant de la <span>viande crue ou peu cuite</span> contenant des <span>larves enkystées</span> → migration vers <span>les</span> <span>muscles striés</span></td>\n            <td><span>Polymyosite fébrile</span> + <span>œdème de la face</span> ; <span>évolution grave voire mortelle</span> à la phase précoce de dissémination larvaire</td>\n          </tr>\n          <tr>\n            <td><strong><span>Anisakiase</span></strong></td>\n            <td>Zoonose des <strong>mers froides</strong> ; ingestion de <span>poisson infesté de larves</span> (cru, mariné ou mal cuit)</td>\n            <td>Symptômes digestifs précoces (<span>gastralgies</span>, <span>nausées</span>, <span>vomissements</span>) ± <span>réactions allergiques</span> intestinales ou généralisées</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 172 — Parasitose digestive · 173 — Zoonose</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":0},{"id":"179-3","rang":"A","rubrique":"Définition","titre":"Savoir préciser les principaux risques liés à la consommation d’eau","contenu":"<div class=\"notion-course\"><p>On distingue <strong>quatre types de risques sanitaires</strong> liés à l'eau et à l'alimentation : <span>biologiques</span> (<span>bactérien</span>, viral, parasitaire, fongique, ATNC), <span>physiques</span> (noyade, brûlure, radioactivité, phénomènes naturels), <span>chimiques</span> (nitrates, métaux lourds, pesticides, additifs…) et <span>autres</span> (<span>allergie</span>, troubles nutritifs, réservoir de vecteurs). Pour l'eau, on retient trois familles.</p>\n      <table>\n        <thead><tr><th>Famille</th><th>Risques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Risques physiques</strong></td>\n            <td><strong>Brûlures :</strong> à l'eau chaude, surtout l'enfant de <span>1 à 4 ans</span> (accidents domestiques)<br>\n            <strong><span class=\"nc-red_bg\">Noyades</span> :</strong> en eau douce ou en eau de mer, lors d'activités de loisir ou professionnelles<br>\n            <strong>Activité subaquatique :</strong> risques liés à la plongée de loisir ou professionnelle</td>\n          </tr>\n          <tr>\n            <td><strong>Risques chimiques</strong></td>\n            <td><strong>Pollution minérale :</strong> éléments nocifs en excès — <span>métaux lourds</span> (plomb, mercure, arsenic, chrome)<br>\n            <strong>Pollutions organiques :</strong> <span>pesticides</span>, <span>nitrites</span>… → <span>méthémoglobinémie</span>, <span>saturnisme</span>, neurotoxicité, cancérogenèse</td>\n          </tr>\n          <tr>\n            <td><strong>Risques <span>infectieux</span></strong></td>\n            <td><strong>Bactéries :</strong> <span><span class=\"nc-purple_bg\">Salmonella</span></span> typhi/paratyphi (typhoïde), <span>Vibrio cholerae</span> (choléra), <span>E. coli</span>, <span><span class=\"nc-purple_bg\">Shigella</span></span>, <span>Campylobacter</span>, <span>Yersinia</span><br>\n            <strong>Virus :</strong> <span>hépatites A et E</span>, <span>rotavirus</span>, <span class=\"nc-purple_bg\">norovirus</span><br>\n            <strong>Parasites :</strong> amoebose, cryptosporidiose, giardiose (cf. obj-0)<br>\n            <strong>ATNC :</strong> <span>prions</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> La <span>diarrhée</span> est une conséquence fréquente des pathologies hydriques — c'est la <strong>2ᵉ cause de <span>mortalité</span> de l'enfant de <span>moins de 5 ans</span></strong>. En Europe, la sécurité sanitaire est encadrée par le « <span>paquet hygiène</span> » (règlements européens).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 167 — Hépatites virales · 176 — <span>Diarrhée</span> infectieuse · 175 — Voyage en pays tropical</em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Les prions concernent notamment des risques alimentaires et iatrogènes ; ne pas les présenter comme un agent usuel de diarrhée transmise par l’eau de boisson. Les rangs mondiaux de mortalité doivent être accompagnés de leur année.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":0},{"id":"179-4","rang":"B","rubrique":"Définition","titre":"Savoir préciser les sources de pollution de l’eau","contenu":"<div class=\"notion-course\"><p>La <span>pollution de l'eau</span> provient de trois sources principales, selon l'activité humaine en cause.</p>\n      <table>\n        <thead><tr><th>Source</th><th>Origine</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">Pollution domestique</span></span></strong></td>\n            <td>Liée à l'<strong>utilisation quotidienne de l'eau au domicile</strong> : eaux de toilettes et de lavage contenant détergents, produits ménagers, graisses et résidus</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">Pollution agricole</span></span></strong></td>\n            <td>Liée à l'<strong>exploitation agricole intensive</strong> (élevage et cultures végétales) : déchets physiologiques de l'élevage, engrais, herbicides, <span>pesticides</span></td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">Pollution industrielle</span></span></strong></td>\n            <td>Liée aux <strong>rejets de tous types d'industries</strong> : effluents industriels, chauffage, stagnation de l'eau, hôpitaux</td>\n          </tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":0},{"id":"179-5","rang":"A","rubrique":"Définition","titre":"Connaître les mesures de prévention des risques sanitaires liés à l’eau","contenu":"<div class=\"notion-course\"><ul><li>Eau potable : respect de limites et références de qualité microbiologiques et chimiques ; une <span class=\"nc-green_bg\">eau claire</span> et <span class=\"nc-green_bg\">sans odeur</span> n’est pas nécessairement potable.</li><li>Prévenir contamination des captages et réseaux, traiter et contrôler l’eau, assurer assainissement et surveillance. Les exigences chimiques sont des concentrations limites, pas une absence absolue de toute molécule.</li><li>Le contrôle sanitaire relève des autorités sanitaires avec <span class=\"nc-yellow_bg\">laboratoires agréés</span> ; le responsable de distribution assure aussi sa surveillance. Respecter les alertes et consignes locales.</li><li>En voyage, choisir une eau sûre et une méthode adaptée ; filtration, désinfection et ébullition n’ont pas une efficacité identique contre tous les agents. Prévenir aussi les expositions lors de baignades.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":0},{"id":"179-6","rang":"A","rubrique":"Définition","titre":"Savoir préciser les principaux risques liés à l’alimentation","contenu":"<div class=\"notion-course\"><p>Pour l'alimentation, <strong>deux risques prédominants</strong> sont à distinguer.</p>\n      <table>\n        <thead><tr><th>Risque</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Nutrition</span></strong></td>\n            <td>Troubles nutritifs (<span>obésité</span>, <span>anorexie</span>) ; <span>allergies alimentaires</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Salubrité alimentaire</span></strong></td>\n            <td><strong>Risque <span>infectieux</span> :</strong> sur toute la chaîne alimentaire (matière première → distribution, y compris pathologies des mains sales) — conventionnel (<span>bactérien</span>, parasitaire, fongique, viral, toxinique) ou non conventionnel (<span>prion</span>)<br>\n            <strong>Risque chimique :</strong> additifs, polluants, antibiotiques, toxiques<br>\n            <strong>Risque physique :</strong> radioactivité</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 167 — Hépatites virales</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":0},{"id":"179-7","rang":"A","rubrique":"Définition","titre":"Savoir définir une toxi-infection alimentaire collective (TIAC) et connaître les différentes symptomatologies de TIAC","contenu":"<div class=\"notion-course\"><p>Une <strong><span>toxi-infection alimentaire collective (TIAC)</span></strong> se définit par l'apparition d'<strong><span>≥ 2 cas</span></strong> d'une symptomatologie, en général digestive, dont on peut rapporter la cause à une <strong><span class=\"nc-yellow_bg\">même origine alimentaire</span></strong>. La TIAC est une <strong><span><span class=\"nc-red nc-bold\">maladie à déclaration obligatoire</span> (MDO)</span></strong>.</p>\n      <p><strong>Cause</strong> — consommation d'aliments contaminés, soit par des bactéries / virus / parasites, soit par des <span>toxines</span> bactériennes. La <span>toxinogénèse</span> a lieu :</p>\n      <ul>\n        <li>soit <strong>dans l'aliment</strong> — <span><span class=\"nc-purple_bg\">S. aureus</span></span>, <span class=\"nc-purple_bg\">toxine thermostable de </span><span><span class=\"nc-purple_bg\">B. cereus</span></span>, <span><span class=\"nc-purple_bg\">Clostridium botulinum</span></span> ;</li>\n        <li>soit <strong>dans la lumière digestive</strong> — toxine thermolabile de <span><span class=\"nc-purple_bg\">B. cereus</span></span>, <span>C. perfringens</span>.</li>\n      </ul>\n      <p>Aliments <span>les</span> plus incriminés : <strong><span class=\"nc-blue_bg\">viandes de volaille</span>, <span class=\"nc-blue_bg\">aliments à base d'œufs</span>, <span class=\"nc-blue_bg\">fruits de mer</span></strong>. Facteurs favorisants : <span>rupture de la chaîne du froid</span>, erreurs de préparation, délai trop long entre préparation et consommation.</p>\n      <p><strong>Symptomatologies de TIAC</strong> :</p>\n      <table>\n        <thead><tr><th>Tableau</th><th>Clinique &amp; incubation</th><th>Germes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Entéro-toxinogène</strong> (cholériforme)</td>\n            <td><span>Diarrhée liquide abondante</span> + <span><span class=\"nc-blue_bg\">vomissements</span></span> + <strong>absence de <span>fièvre</span></strong><br>Incubation <span><span class=\"nc-pink nc-bold\">courte</span></span> (quelques <span class=\"nc-pink nc-bold\">heures</span>)</td>\n            <td><span><span class=\"nc-purple_bg\">Norovirus</span></span>, <span>C. perfringens</span>, <span><span class=\"nc-purple_bg\">B. cereus</span></span>, <span><span class=\"nc-purple_bg\">E. coli</span></span><span class=\"nc-purple_bg\"> entérotoxinogène</span></td>\n          </tr>\n          <tr>\n            <td><strong>Entéro-invasif</strong> (dysentérique)</td>\n            <td><span><span class=\"nc-red_bg\">Fièvre</span></span> + <span><span class=\"nc-red_bg\">diarrhée afécale glairosanglante</span></span> + <span>douleurs abdominales</span><br>Incubation <span><span class=\"nc-pink nc-bold\">longue</span></span> (<span>24 à 72 h</span>)</td>\n            <td><span><span class=\"nc-purple_bg\">Salmonella</span></span>, <span><span class=\"nc-purple_bg\">Campylobacter jejuni</span></span>, <span><span class=\"nc-purple_bg\">Vibrio parahaemolyticus</span></span>, <span><span class=\"nc-purple_bg\">E. coli</span></span><span class=\"nc-purple_bg\"> entéro-invasif,</span> <span>Yersinia</span>, <span><span class=\"nc-purple_bg\">Shigella</span></span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Hépatite</span> aiguë</strong></td>\n            <td>Tableau d'<span>hépatite</span> <span>virale</span> aiguë</td>\n            <td><span>VHA</span>, <span>VHE</span></td>\n          </tr>\n          <tr>\n            <td><strong>Expression extradigestive / neurologique</strong></td>\n            <td>Manifestations cutanées (<span>érythème</span>, bouffées vasomotrices) ; <span>manifestations neurologiques</span> (botulisme : diplopie, paralysie flasque descendante)</td>\n            <td><span>C. botulinum</span>, <span class=\"nc-purple_bg\">neurotoxines de dinoflagellés</span>, <span class=\"nc-pink_bg\">histamine</span> (poisson avarié)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant.</strong> Des cas <strong>très groupés dans le temps</strong> orientent vers une incubation <span><span class=\"nc-pink nc-bold\">courte</span></span> (source ponctuelle) ; des cas <strong>dispersés</strong> après le repas commun orientent vers une incubation <span><span class=\"nc-pink nc-bold\">longue</span></span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 176 — <span>Diarrhée</span> infectieuse</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":0},{"id":"179-8","rang":"A","rubrique":"Étiologies","titre":"Connaître les agents pathogènes responsable de TIAC","contenu":"<div class=\"notion-course\"><p><span>Les</span> agents responsables de TIAC se classent selon leur <strong>mécanisme</strong> et leur <strong>durée d'incubation</strong>.</p>\n      <table>\n        <thead><tr><th>Agent</th><th>Incubation</th><th>Clinique</th><th>Aliment vecteur</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-purple_bg\">Salmonella</span> enterica</span></strong> non typhi</td>\n            <td><span>12 à 24 h</span></td>\n            <td><span>Diarrhée aiguë fébrile</span></td>\n            <td>Viandes, volailles, œufs, <span class=\"nc-blue_bg\">fruits de mer</span> peu/pas cuits</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-purple_bg\">Staphylococcus aureus</span></span></strong></td>\n            <td><span>2 à 4 h</span></td>\n            <td><span><span class=\"nc-blue_bg\">Vomissements</span></span>, <span><span class=\"nc-red_bg\">douleurs abdominales</span></span>, <span>diarrhée</span>, <strong><span class=\"nc-blue_bg\">absence de </span><span><span class=\"nc-blue_bg\">fièvre</span></span></strong></td>\n            <td>Lait et dérivés, plats cuisinés la veille ; porteur sain / staphylococcie cutanée</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-purple_bg\">Clostridium perfringens</span></span></strong></td>\n            <td><span>8 à 24 h</span></td>\n            <td><span>Diarrhée aiguë</span>, <span class=\"nc-blue_bg\">absence de </span><span><span class=\"nc-blue_bg\">fièvre</span></span></td>\n            <td>Plats cuisinés la veille, réfrigération insuffisante, restauration collective</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-purple_bg\">Norovirus</span></span></strong></td>\n            <td><span>24 à 48 h</span></td>\n            <td><span><span class=\"nc-blue_bg\">Vomissements</span></span>, <span><span class=\"nc-red_bg\">douleurs abdominales</span></span>, <span>diarrhée</span> peu/pas fébrile</td>\n            <td>Coquillages, crustacés, crudités</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-purple_bg\">Clostridium botulinum</span></span></strong></td>\n            <td><span>12 à 72 h</span></td>\n            <td><span>Botulisme</span> (voir encadré ci-dessous)</td>\n            <td>Jambon, conserves artisanales</td>\n          </tr>\n          <tr>\n            <td><strong>Intoxication histaminique</strong></td>\n            <td><span>10 min à 1 h</span></td>\n            <td><span class=\"nc-blue_bg\">Troubles vasomoteurs</span> (face, cou), <span><span class=\"nc-blue_bg\">céphalées</span></span>, <span class=\"nc-blue_bg\">troubles digestifs</span></td>\n            <td>Poisson mal conservé (thon, maquereau)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Le tableau clinique permet de séparer <span>les</span> agents <strong>entéro-invasifs</strong> (incubation <span class=\"nc-pink nc-bold\">longue</span>, <span><span class=\"nc-red_bg\">fièvre</span></span> + <span>diarrhée</span> glairosanglante : <span><span class=\"nc-purple_bg\">Salmonella</span></span>, <span><span class=\"nc-purple_bg\">Shigella</span></span>, <span><span class=\"nc-purple_bg\">Campylobacter jejuni</span></span>, <span><span class=\"nc-purple_bg\">Yersinia enterocolitica</span></span>, <span>Listeria</span>) des agents <strong>entéro-toxinogènes</strong> (incubation <span class=\"nc-pink nc-bold\">courte</span>, toxine préformée, sans <span><span class=\"nc-red_bg\">fièvre</span></span> : <span><span class=\"nc-purple_bg\">S. aureus</span></span>, <span><span class=\"nc-purple_bg\">B. cereus</span></span>, <span>C. perfringens</span>).</p>\n      <div class=\"callout callout-danger\">\n        <strong><span>Urgence</span> — TIAC à <span>E. coli</span> entérohémorragique (O157:H7).</strong> Enfant de <span>moins de 5 ans</span> (1ʳᵉ cause d'<span>IRA</span> organique avant <span>3 ans</span>), après produits peu/pas cuits (lait, viande). <span>Évolution</span> en 3 phases : <span>phase digestive</span> (<span>diarrhée</span> sanglante) → <span>phase hématologique</span> (microangiopathie <span>thrombotique</span> : <span>anémie hémolytique</span> + <span>thrombopénie</span>) → <span>phase rénale</span> (<span>IRA</span> oligoanurique, dialyse dans <span>50 %</span> des cas). PEC <span>symptomatique</span> ± <span>épuration extra-rénale</span> ; prévention = interdiction des laitages non pasteurisés et des viandes crues avant <span>5 ans</span>.\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Botulisme.</strong> Toxine bloquant <span>les</span> synapses cholinergiques. Phase d'état : <span><span class=\"nc-red_bg\">syndrome parasympathicolytique</span></span> (mydriase, sécheresse buccale, <span>dysphagie</span>, <span>constipation</span>, <span>dysurie</span>) + <span><span class=\"nc-red_bg\">paralysie descendante</span></span> — mais <strong><span class=\"nc-blue_bg\">absence de </span><span><span class=\"nc-blue_bg\">fièvre</span></span></strong>, <strong>vigilance normale</strong>, pas de <span>syndrome méningé</span>. <span><span class=\"nc-pink_bg\">Réanimation</span> + <span class=\"nc-pink_bg\">sérothérapie</span></span> si <span class=\"nc-red nc-bold\">atteinte respiratoire</span>.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant clé.</strong> Incubation <span>&lt; 24 h</span> + <span><span class=\"nc-blue_bg\">vomissements</span></span> <strong>sans <span><span class=\"nc-red_bg\">fièvre</span></span></strong> → <span>toxine préformée</span> (<span class=\"nc-purple_bg\">S. aureus</span>, <span class=\"nc-purple_bg\">B. cereus</span>). Incubation <span><span class=\"nc-pink nc-bold\">&gt; 24 h</span></span> + <strong><span><span class=\"nc-red_bg\">fièvre</span></span></strong> → <span>infection entéro-invasive</span> (<span><span class=\"nc-purple_bg\">Salmonella</span></span>, <span class=\"nc-purple_bg\">Shigella</span>, Campylobacter).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 176 — <span>Diarrhée</span> infectieuse · 286 — <span>Diarrhée</span> aiguë - <span>déshydratation</span></em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Botulisme suspect : urgence spécialisée et discussion précoce de l’antitoxine, sans attendre une insuffisance respiratoire. STEC/EHEC : surveiller SHU ; éviter ralentisseurs du transit et antibiothérapie systématique, qui peut être délétère. Les durées d’incubation se recouvrent et ne prouvent pas à elles seules l’agent.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":0},{"id":"179-9","rang":"A","rubrique":"Définition","titre":"Connaître les modalités de détection et de signalement d’une suspicion de TIAC","contenu":"<div class=\"notion-course\"><p>Devant une suspicion de TIAC, deux temps : <strong>détecter</strong> puis <strong>signaler</strong> <span class=\"nc-red nc-bold\">sans délai</span>.</p>\n      <p><strong><span>Détecter</span></strong> — réunir trois éléments :</p>\n      <ul>\n        <li>une <span>symptomatologie compatible</span> avec une TIAC (forme digestive ± extradigestive) ;</li>\n        <li>au moins <strong><span>2 cas groupés</span></strong> dans le temps et l'espace (la « notion de cas » est définie sur la symptomatologie) ;</li>\n        <li>une <strong><span class=\"nc-blue_bg\">origine alimentaire commune</span></strong>.</li>\n      </ul>\n      <p><strong><span>Signaler</span></strong> — le <span>signalement</span> est une <strong><span>procédure d'urgence et d'alerte, <span class=\"nc-red nc-bold\">sans délai</span></span></strong> :</p>\n      <table>\n        <thead><tr><th>Question</th><th>Réponse</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Comment ?</strong></td><td>Par <strong><span class=\"nc-red nc-bold\">tout moyen approprié</span></strong> — <span class=\"nc-red nc-bold\">téléphone</span>, <span class=\"nc-red nc-bold\">fax</span></td></tr>\n          <tr><td><strong>À qui ?</strong></td><td>Au <span class=\"nc-blue_bg\">médecin de l'</span><span><span class=\"nc-blue_bg\">ARS</span></span><span class=\"nc-blue_bg\"> (car MDO)</span> <strong>et</strong> à la <span><span class=\"nc-blue_bg\">DDPP</span></span><span class=\"nc-blue_bg\"> (direction départementale de la protection des populations)</span></td></tr>\n          <tr><td><strong>Ensuite ?</strong></td><td><span>Notification</span> de la déclaration via un formulaire dédié à l'<span>ARS</span></td></tr>\n        </tbody>\n      </table>\n      <p>Conserver tous <span>les</span> restes des derniers repas à <span>4 °C</span> pour les mettre à disposition de la <span class=\"nc-yellow_bg\">DDPP</span>.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Ne pas confondre le <strong><span>signalement</span></strong> (immédiat, <span>urgence</span>, par tout moyen) et la <strong>notification</strong> (différée, sur formulaire dédié).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 181 — Sécurité sanitaire des produits - Veille sanitaire</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":3},{"id":"179-10","rang":"B","rubrique":"Définition","titre":"Connaître les différentes étapes d’une investigation de TIAC","contenu":"<div class=\"notion-course\"><ul><li>Définir les <span class=\"nc-blue_bg\">cas</span>, recenser malades et personnes exposées non malades, décrire dates/symptômes et recueillir les aliments consommés. Conserver restes et plats témoins dans les conditions demandées par les enquêteurs.</li><li>Enquête clinique et épidémiologique, enquête alimentaire et enquête sanitaire sont coordonnées ; prélèvements chez les patients et dans les aliments orientés par les hypothèses.</li><li>Cohorte rétrospective si la population exposée est bien définie et accessible ; cas-témoins si elle ne l’est pas. Le choix ne dépend pas d’un seuil rigide de trente personnes.</li><li>Comparer taux d’attaque, risques relatifs ou odds ratios avec leurs incertitudes et biais. Une valeur supérieure à un ne suffit pas, seule, à prouver l’aliment responsable.</li><li>Prendre les mesures de contrôle dès qu’indiquées puis produire un bilan ; les investigations ne doivent pas retarder la maîtrise de l’exposition.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":7},{"id":"179-11","rang":"A","rubrique":"Définition","titre":"Connaître les mesures de prévention des TIAC","contenu":"<div class=\"notion-course\"><ul><li>Prévention : hygiène des mains et des locaux, séparation cru/cuit et propre/souillé, maîtrise des températures et délais, cuisson adaptée et protection des aliments.</li><li>Former le personnel, signaler les symptômes pouvant contaminer les aliments et adapter ou suspendre les tâches à risque. Appliquer le plan de maîtrise sanitaire et la démarche HACCP.</li><li>Autocontrôles et <span class=\"nc-blue_bg\">contrôles</span> officiels selon obligations, analyse du risque et secteur ; ne pas décrire une analyse systématique par l’<span class=\"nc-red nc-bold\">ARS</span> de tous les plats servis.</li><li>En restauration collective concernée, les plats témoins sont conservés de manière habituelle pour permettre une investigation ultérieure : leur conservation ne commence pas seulement après une TIAC. Signalement immédiat si cas groupés suspects.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.santepubliquefrance.fr/maladies-a-signalement-obligatoire\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · maladies à signalement obligatoire, 2026</a></li></ul></details>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>MDO :</strong> la <span class=\"kw-def\">TIAC</span> est une <span class=\"kw-alerte\">maladie à déclaration obligatoire</span> — <span class=\"kw-def\">signalement</span> <span class=\"kw-alerte\">sans délai</span> (procédure d’<span class=\"kw-alerte\">urgence</span> et d’alerte).</p><p><strong>Signaler :</strong> par <strong>tout moyen approprié</strong> (<span class=\"kw-chiffre\">téléphone</span>, fax) au médecin de l’<span class=\"kw-def\">ARS</span> <strong>et</strong> à la <span class=\"kw-def\">DDPP</span> ; <span class=\"kw-def\">notification</span> différée sur formulaire dédié.</p><p><strong>Conserver :</strong> tous <span class=\"kw-clinique\">les</span> restes des derniers repas à <span class=\"kw-chiffre\">4 °C</span> (<span class=\"kw-ci\">pas au congélateur</span>) pour la DDPP.</p><p><strong>Urgences vitales :</strong> <span class=\"kw-alerte\">botulisme</span> (paralysie respiratoire) et <span class=\"kw-alerte\">SHU à EHEC</span> de l’enfant.</p>","hospit":"<p><strong>Principe :</strong> la majorité des TIAC sont bénignes et prises en charge en <strong>ambulatoire</strong> ; l’<span class=\"kw-alerte\">hospitalisation</span> se discute sur la tolérance et le <span class=\"kw-def\">terrain</span>.</p><ul><li><span class=\"kw-alerte\">Hospitalisation</span> à <strong>discuter</strong> en cas de <span class=\"kw-clinique\">forte intolérance à la prise alimentaire</span> et de <span class=\"kw-clinique\">perte de poids importante</span> (surtout l’<span class=\"kw-clinique\">enfant</span>).</li><li><span class=\"kw-alerte\">Botulisme</span> : <span class=\"kw-ttt\">hospitalisation</span> systématique ; <span class=\"kw-ttt\">réanimation</span> si atteinte respiratoire.</li><li><span class=\"kw-alerte\">SHU à EHEC</span> de l’enfant : <span class=\"kw-ttt\">hospitalisation</span>, recours à l’<span class=\"kw-ttt\">épuration extra-rénale</span> si IRA oligoanurique.</li><li>Intoxication <span class=\"kw-etio\">histaminique</span> : régression rapide → prise en charge <strong>ambulatoire</strong>.</li><li>En milieu hospitalier, invest<span class=\"kw-chiffre\">iga</span>tion conduite avec l’<span class=\"kw-def\">équipe opérationnelle d’hygiène (EOH)</span>.</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Diarrhée sanglante</span> chez l’<span class=\"kw-clinique\">enfant de &lt; 5 ans</span> → risque de <span class=\"kw-alerte\">SHU</span> (EHEC O157:H7).</li><li><span class=\"kw-bio\">Anémie hémolytique</span> + <span class=\"kw-bio\">thrombopénie</span> + <span class=\"kw-alerte\">IRA oligoanurique</span> (microangiopathie <span class=\"kw-etio\">thrombotique</span> du SHU).</li><li><span class=\"kw-alerte\">Paralysie descendante</span> atteignant <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">muscles respiratoires</span> (botulisme).</li><li><span class=\"kw-alerte\">Déshydratation</span> avec <span class=\"kw-ci\">intolérance</span> alimentaire totale, surtout chez l’<span class=\"kw-clinique\">enfant</span>.</li><li><span class=\"kw-clinique\">Femme enceinte</span> ou <span class=\"kw-clinique\">immunodéprimé</span> → formes graves de <span class=\"kw-etio\">listériose</span> (atteinte neuroméningée, fausse couche).</li></ul>","principes":"<p><strong>Principe :</strong> prise en charge avant tout <span class=\"kw-ttt\">symptomatique</span> ; l’<span class=\"kw-ci\">antibiothérapie n’est pas indiquée en 1ʳᵉ intention</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">antidiarrhéiques sont à éviter, voire contre-indiqués</span>.</p><ul><li><span class=\"kw-ttt\">Réhydratation</span> adaptée : apports <span class=\"kw-ttt\">sodés</span> et <span class=\"kw-ttt\">sucrés</span>.</li><li>Lutte contre <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">nausées</span> et <span class=\"kw-clinique\">vomissements</span> ; <span class=\"kw-ttt\">antipyrétique</span> si nécessaire.</li><li><span class=\"kw-ttt\">Antispasmodiques</span> et <span class=\"kw-ttt\">pansements digestifs</span> administrés si nécessaire.</li><li><span class=\"kw-bio\">Coproculture</span> : peut être indiquée.</li><li><span class=\"kw-ci\">Antibiothérapie non indiquée en 1ʳᵉ intention</span>.</li><li><span class=\"kw-ci\">Antidiarrhéiques à éviter, voire contre-indiqués</span>.</li></ul><p><strong><span class=\"kw-etio\">Botulisme</span></strong></p><ul><li><span class=\"kw-ttt\">Hospitalisation</span> + traitement <span class=\"kw-ttt\">symptomatique</span>.</li><li>Si atteinte respiratoire : <span class=\"kw-ttt\">réanimation</span> + <span class=\"kw-ttt\">sérothérapie</span> (antitoxine botulinique).</li></ul><p><strong>Intoxication <span class=\"kw-etio\">histaminique</span></strong></p><ul><li>Régression rapide, accélérée par <span class=\"kw-ttt\">antihistaminiques</span> et <span class=\"kw-ttt\">corticoïdes</span>.</li></ul><p><strong><span class=\"kw-etio\">EHEC</span> / <span class=\"kw-def\">SHU</span> de l’enfant</strong></p><ul><li>Traitement <span class=\"kw-ttt\">symptomatique</span> ; recours parfois à l’<span class=\"kw-ttt\">épuration extra-rénale</span> (dialyse dans <span class=\"kw-chiffre\">50 %</span> des cas).</li></ul>","suivi":"<p><strong>Détecter :</strong> <span class=\"kw-chiffre\">≥ 2 cas</span> groupés (temps, espace) + <span class=\"kw-clinique\">symptomatologie compatible</span> + <strong>origine alimentaire commune</strong>.</p><p><strong>Investiguer :</strong> trois enquêtes coordonnées par l’<span class=\"kw-def\">ARS</span> / <span class=\"kw-def\">DDPP</span> — <span class=\"kw-def\">clinique-épidémiologique</span>, <span class=\"kw-def\">alimentaire</span>, <span class=\"kw-def\">microbiologique</span>.</p><p><strong>Conserver :</strong> plats témoins <span class=\"kw-chiffre\">3-5 jours</span> en chambre froide en restauration collective (mesure appliquée seulement si TIAC déclarée).</p><ul><li>Enquête <span class=\"kw-def\">clinique</span> : recensement des cas et indemnes → <span class=\"kw-bio\">taux d’attaque</span> ; <span class=\"kw-bio\">courbe épidémique</span> (un <span class=\"kw-clinique\">pic</span> signe une source ponctuelle).</li><li>Enquête <span class=\"kw-def\">alimentaire</span> : <span class=\"kw-bio\">risque relatif (RR)</span> par étude de cohorte (collectivité &lt; 30) ou <span class=\"kw-bio\">odds ratio (OR)</span> par étude cas-témoins (&gt; 30) — &gt; 1 = aliment suspect.</li><li>Enquête <span class=\"kw-def\">microbiologique</span> : prélèvements patient (<span class=\"kw-bio\">selles</span>, <span class=\"kw-bio\">sang</span>, <span class=\"kw-clinique\">vomissements</span>) et restes/plats témoins ; agent retrouvé dans <span class=\"kw-chiffre\">¼ des TIAC</span> seulement.</li><li><span class=\"kw-def\">Surveillance</span> <span class=\"kw-ttt\">biologique</span> du <span class=\"kw-def\">SHU</span> : <span class=\"kw-bio\">NFS-plaquettes</span>, <span class=\"kw-bio\">schizocytes</span>, <span class=\"kw-bio\">bilan rénal</span>.</li><li>Prévention <em>a posteriori</em> : enquête sanitaire (DDPP / EOH), vérification du système <span class=\"kw-def\">HACCP</span>, actions correctives.</li></ul>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion de TIAC — ≥ 2 cas, même origine alimentaire commune","detail":"<h4>CAT — Orientation étiologique d’une TIAC — Incubation × <span class=\"kw-clinique\">fièvre</span> × type de <span class=\"kw-clinique\">diarrhée</span></h4>","branches":[{"to":"t-botulisme","label":"Signes neuro: diplopie, paralysie descendante, sans fièvre","color":"red"},{"to":"t-histamine","label":"Troubles vasomoteurs (face, cou), céphalées — poisson","color":"blue"},{"to":"q-digestif","label":"Tableau digestif prédominant","color":"green"}]},{"id":"t-botulisme","kind":"terminal","label":"Botulisme","color":"red","detail":"<h4>Clinique</h4><ul><li>Phase d’invasion : <span class=\"kw-clinique\">troubles digestifs</span> transitoires, <span class=\"kw-clinique\">pseudo-presbytie</span>.</li><li>Phase d’état : <span class=\"kw-clinique\">syndrome parasympathicolytique</span> (<span class=\"kw-clinique\">mydriase</span>, sécheresse buccale, <span class=\"kw-clinique\">dysphagie</span>, <span class=\"kw-clinique\">constipation</span>, <span class=\"kw-clinique\">dysurie</span>).</li><li><span class=\"kw-alerte\">Paralysie descendante</span> : nerfs crâniens → membres → muscles respiratoires.</li><li><strong>Absence de <span class=\"kw-clinique\">fièvre</span></strong>, vigilance normale, pas de <span class=\"kw-clinique\">syndrome méningé</span>.</li></ul><h4>Délai</h4><ul><li>Incubation <span class=\"kw-chiffre\">12 à 72 h</span>. Origine : <span class=\"kw-etio\">jambon</span>, <span class=\"kw-etio\">conserves artisanales</span> (toxine préformée).</li></ul><h4>Paraclinique</h4><ul><li>Mise en évidence de la <span class=\"kw-bio\">toxine botulinique</span> (aliment incriminé, voire sang, <span class=\"kw-clinique\">vomissements</span>, selles) ; <span class=\"kw-bio\">électromyographie</span> (bloc de conduction neuromusculaire).</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Hospitalisation</span> + traitement <span class=\"kw-ttt\">symptomatique</span>.</li><li>Si atteinte respiratoire : <span class=\"kw-ttt\">réanimation</span> + <span class=\"kw-ttt\">sérothérapie</span> (antitoxine botulinique).</li></ul>"},{"id":"t-histamine","kind":"terminal","label":"Intoxication histaminique","color":"blue","detail":"<h4>Clinique</h4><ul><li>Troubles <span class=\"kw-clinique\">vasomoteurs</span> (<span class=\"kw-clinique\">érythème facial</span>, face et cou), <span class=\"kw-clinique\">céphalées</span>, troubles digestifs.</li></ul><h4>Délai</h4><ul><li>Incubation <span class=\"kw-chiffre\">très courte (10 min à 1 h)</span>. Origine : <span class=\"kw-etio\">poisson mal conservé</span> (thon, maquereau).</li></ul><h4>Paraclinique</h4><ul><li>Diagnostic <strong>clinique</strong>.</li></ul><h4>Traitement</h4><ul><li>Régression rapide, accélérée par <span class=\"kw-ttt\">antihistaminiques</span> et <span class=\"kw-ttt\">corticoïdes</span>.</li></ul>"},{"id":"q-digestif","kind":"decision","label":"Incubation, fièvre et type de diarrhée ? — Discriminant clé de l’orientation étiologique","branches":[{"to":"q-toxine","label":"Incubation < 24 h, vomissements, SANS fièvre","color":"green"},{"to":"t-noro","label":"Coquillages/crudités, peu fébrile (24-48 h)","color":"green"},{"to":"q-invasif","label":"Incubation > 24 h, fièvre, diarrhée glairosanglante","color":"amber"}]},{"id":"q-toxine","kind":"decision","label":"Aliment en cause ? — Toxine préformée dans l’aliment","branches":[{"to":"t-staph","label":"Pâtisserie, viande manipulée (2-4 h)","color":"green"},{"to":"t-bcereus","label":"Riz, soja à température ambiante","color":"green"},{"to":"t-perfringens","label":"Plats cuisinés la veille (8-24 h)","color":"green"}]},{"id":"t-staph","kind":"terminal","label":"Staphylococcus aureus","color":"green","detail":"<h4>Clinique</h4><ul><li>Début brutal : <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">douleurs abdominales</span>, <span class=\"kw-clinique\">diarrhée</span>, <strong>sans <span class=\"kw-clinique\">fièvre</span></strong>.</li></ul><h4>Délai</h4><ul><li>Incubation <span class=\"kw-chiffre\">2 à 4 h</span> (<span class=\"kw-etio\">toxine thermostable</span> préformée). Origine : pâtisseries, viande manipulée, lait et dérivés ; <span class=\"kw-etio\">porteur sain</span> / staphylococcie cutanée.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Symptomatique</span> : <span class=\"kw-ttt\">réhydratation</span> ; <span class=\"kw-ci\">pas d’antibiothérapie</span>.</li></ul>"},{"id":"t-bcereus","kind":"terminal","label":"Bacillus cereus","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Nausées</span> et <span class=\"kw-clinique\">vomissements</span> (<span class=\"kw-chiffre\">1 à 6 h</span>, toxine émétisante) ou <span class=\"kw-clinique\">diarrhée aqueuse profuse</span> (<span class=\"kw-chiffre\">6 à 12 h</span>, entérotoxine).</li></ul><h4>Délai</h4><ul><li>Origine : <span class=\"kw-etio\">riz</span>, <span class=\"kw-etio\">soja</span> ayant séjourné à température ambiante.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Symptomatique</span> : <span class=\"kw-ttt\">réhydratation</span>.</li></ul>"},{"id":"t-perfringens","kind":"terminal","label":"Clostridium perfringens","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Diarrhée</span> et <span class=\"kw-clinique\">douleurs abdominales</span>, <strong>sans <span class=\"kw-clinique\">fièvre</span></strong>.</li></ul><h4>Délai</h4><ul><li>Incubation <span class=\"kw-chiffre\">8 à 24 h</span>. Origine : <span class=\"kw-etio\">plats cuisinés la veille</span>, réfrigération insuffisante, restauration collective.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Symptomatique</span> : <span class=\"kw-ttt\">réhydratation</span>.</li></ul>"},{"id":"t-noro","kind":"terminal","label":"Norovirus","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Vomissements</span>, <span class=\"kw-clinique\">douleurs abdominales</span>, <span class=\"kw-clinique\">diarrhée</span> peu ou pas fébrile.</li></ul><h4>Délai</h4><ul><li>Incubation <span class=\"kw-chiffre\">24 à 48 h</span>. Origine : <span class=\"kw-etio\">coquillages</span>, <span class=\"kw-etio\">crustacés</span>, <span class=\"kw-etio\">crudités</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Symptomatique</span> : <span class=\"kw-ttt\">réhydratation</span>.</li></ul>"},{"id":"q-invasif","kind":"decision","label":"Terrain et sévérité ? — Tableau entéro-invasif (dysentérique)","branches":[{"to":"t-ehec","label":"Diarrhée sanglante, enfant < 5 ans → SHU","color":"red"},{"to":"t-invasif","label":"Diarrhée fébrile, adulte","color":"amber"}]},{"id":"t-ehec","kind":"terminal","label":"E. coli entérohémorragique (O157:H7)","color":"red","detail":"<h4>Clinique</h4><ul><li>Phase digestive : <span class=\"kw-clinique\">diarrhée sanglante</span> entéro-invasive.</li><li>Phase hématologique : microangiopathie <span class=\"kw-etio\">thrombotique</span> (<span class=\"kw-bio\">anémie hémolytique</span> + <span class=\"kw-bio\">thrombopénie</span>).</li><li>Phase rénale : <span class=\"kw-alerte\">IRA oligoanurique</span> (<span class=\"kw-def\">syndrome hémolytique et urémique</span>).</li></ul><h4>Délai</h4><ul><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-clinique\">enfant de &lt; 5 ans</span> (1ʳᵉ cause d’IRA organique avant <span class=\"kw-chiffre\">3 ans</span>). Origine : produits peu/pas cuits (<span class=\"kw-etio\">lait cru</span>, <span class=\"kw-etio\">viande hachée</span>).</li></ul><h4>Paraclinique</h4><ul><li>Confirmation en <span class=\"kw-bio\">laboratoire spécialisé</span> ; bilan des complications : <span class=\"kw-bio\">NFS-plaquettes</span>, <span class=\"kw-bio\">schizocytes</span>, <span class=\"kw-bio\">bilan rénal</span>.</li></ul><h4>Traitement</h4><ul><li>Traitement <span class=\"kw-ttt\">symptomatique</span> ; recours parfois à l’<span class=\"kw-ttt\">épuration extra-rénale</span> (dialyse dans <span class=\"kw-chiffre\">50 %</span> des cas).</li></ul>"},{"id":"t-invasif","kind":"terminal","label":"TIAC entéro-invasive","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Fièvre</span> + <span class=\"kw-clinique\">diarrhée afécale glairosanglante</span> + <span class=\"kw-clinique\">douleurs abdominales</span>.</li></ul><h4>Étiologie</h4><ul><li><span class=\"kw-etio\">Salmonella</span> non typhique (<span class=\"kw-chiffre\">12-36 h</span>, volailles, œufs, produits laitiers).</li><li><span class=\"kw-etio\">Campylobacter jejuni</span> (<span class=\"kw-chiffre\">2-5 j</span>, volailles, lait non pasteurisé, eau).</li><li><span class=\"kw-etio\">Shigella</span> (<span class=\"kw-chiffre\">2-5 j</span>, <span class=\"kw-clinique\">syndrome dysentérique</span> franc).</li><li><span class=\"kw-etio\">Yersinia enterocolitica</span> (<span class=\"kw-chiffre\">1-11 j</span>, porc, syndrome pseudo-appendiculaire).</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Symptomatique</span> + <span class=\"kw-ttt\">réhydratation</span> ; <span class=\"kw-bio\">coproculture</span> indiquée ; <span class=\"kw-ci\">antibiothérapie non systématique en 1ʳᵉ intention</span>, <span class=\"kw-ci\">antidiarrhéiques à éviter</span>.</li></ul>"}]},"cards":[{"i":"0a1a6984db75","n":179,"o":"179-11","u":"Définition","t":"Connaître les mesures de prévention des TIAC","q":"Quelles sont les règles d'hygiène essentielles à respecter pour la prévention des TIAC, concernant les lieux, le transport, les cuisines et le personnel ?","a":"<div class=\"notion-course\"><ul><li>Prévention : hygiène des mains et des locaux, séparation cru/cuit et propre/souillé, maîtrise des températures et délais, cuisson adaptée et protection des aliments.</li><li>Former le personnel, signaler les symptômes pouvant contaminer les aliments et adapter ou suspendre les tâches à risque. Appliquer le plan de maîtrise sanitaire et la démarche HACCP.</li></ul></div>"},{"i":"20e945925c2f","n":179,"o":"179-11","u":"Définition","t":"Connaître les mesures de prévention des TIAC","q":"Quelles mesures de surveillance du personnel sont préconisées pour prévenir les TIAC ?","a":"<div class=\"notion-course\"><ul><li>Former le personnel, signaler les symptômes pouvant contaminer les aliments et adapter ou suspendre les tâches à risque. Appliquer le plan de maîtrise sanitaire et la démarche HACCP.</li></ul></div>"},{"i":"311b04630f14","n":179,"o":"179-11","u":"Définition","t":"Connaître les mesures de prévention des TIAC","q":"Les plats témoins sont-ils conservés seulement après la déclaration d’une TIAC ?","a":"<div class=\"notion-course\"><ul><li>En restauration collective concernée, les plats témoins sont conservés de manière habituelle pour permettre une investigation ultérieure : leur conservation ne commence pas seulement après une TIAC. Signalement immédiat si cas groupés suspects.</li></ul></div>"},{"i":"549a1db8b3b8","n":179,"o":"179-11","u":"Définition","t":"Connaître les mesures de prévention des TIAC","q":"Quelles sont les trois axes principaux de la prévention des TIAC selon les autorités de santé ?","a":"<div class=\"notion-course\"><ul><li>Prévention : hygiène des mains et des locaux, séparation cru/cuit et propre/souillé, maîtrise des températures et délais, cuisson adaptée et protection des aliments.</li><li>Former le personnel, signaler les symptômes pouvant contaminer les aliments et adapter ou suspendre les tâches à risque. Appliquer le plan de maîtrise sanitaire et la démarche HACCP.</li><li>Autocontrôles et <span class=\"nc-blue_bg\">contrôles</span> officiels selon obligations, analyse du risque et secteur ; ne pas décrire une analyse systématique par l’<span class=\"nc-red nc-bold\">ARS</span> de tous les plats servis.</li></ul></div>"},{"i":"9db224faae36","n":179,"o":"179-11","u":"Définition","t":"Connaître les mesures de prévention des TIAC","q":"Comment est organisé le contrôle des aliments en restauration collective pour prévenir les TIAC et quel système est utilisé ?","a":"<div class=\"notion-course\"><ul><li>Former le personnel, signaler les symptômes pouvant contaminer les aliments et adapter ou suspendre les tâches à risque. Appliquer le plan de maîtrise sanitaire et la démarche HACCP.</li><li>Autocontrôles et <span class=\"nc-blue_bg\">contrôles</span> officiels selon obligations, analyse du risque et secteur ; ne pas décrire une analyse systématique par l’<span class=\"nc-red nc-bold\">ARS</span> de tous les plats servis.</li><li>En restauration collective concernée, les plats témoins sont conservés de manière habituelle pour permettre une investigation ultérieure : leur conservation ne commence pas seulement après une TIAC. Signalement immédiat si cas groupés suspects.</li></ul></div>"},{"i":"504aa15ad776","n":179,"o":"179-3","u":"Définition","t":"Savoir préciser les principaux risques liés à la consommation d’eau","q":"Quels sont les types de risques physiques spécifiques liés à la consommation d'eau ?","a":"<div class=\"notion-course\"><p>Les risques physiques spécifiques liés à l'eau sont :</p><ul><li>Les <strong>brûlures</strong> : à l'eau chaude, particulièrement chez l'enfant de 1 à 4 ans, souvent suite à des accidents domestiques.</li><li>Les <strong><span class=\"nc-red_bg\">noyades</span></strong> : en eau douce ou en eau de mer, lors d'activités de loisir ou professionnelles.</li><li>Les risques liés à l'<strong>activité subaquatique</strong> : en plongée de loisir ou professionnelle.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Les prions concernent notamment des risques alimentaires et iatrogènes ; ne pas les présenter comme un agent usuel de diarrhée transmise par l’eau de boisson. Les rangs mondiaux de mortalité doivent être accompagnés de leur année.</li></ul></div></div>"},{"i":"7883afc953f1","n":179,"o":"179-3","u":"Définition","t":"Savoir préciser les principaux risques liés à la consommation d’eau","q":"Quels sont les types de risques chimiques spécifiques liés à la consommation d'eau ?","a":"<div class=\"notion-course\"><p>Les risques chimiques spécifiques liés à l'eau comprennent :</p><ul><li>Les <strong>pollutions minérales</strong> : éléments nocifs en excès comme les <strong>métaux lourds</strong> (plomb, mercure, arsenic, chrome) pouvant entraîner saturnisme, neurotoxicité ou cancérogenèse.</li><li>Les <strong>pollutions organiques</strong> : notamment les <strong>pesticides</strong> et les <strong>nitrites</strong>, pouvant causer une méthémoglobinémie.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Les prions concernent notamment des risques alimentaires et iatrogènes ; ne pas les présenter comme un agent usuel de diarrhée transmise par l’eau de boisson. Les rangs mondiaux de mortalité doivent être accompagnés de leur année.</li></ul></div></div>"},{"i":"a0d6dc683588","n":179,"o":"179-3","u":"Définition","t":"Savoir préciser les principaux risques liés à la consommation d’eau","q":"Quels sont les types de risques infectieux spécifiques liés à la consommation d'eau ?","a":"<div class=\"notion-course\"><p>Les risques infectieux spécifiques liés à l'eau incluent :</p><ul><li><strong>Bactéries</strong> : <em><span class=\"nc-purple_bg\">Salmonella</span> typhi/paratyphi</em> (typhoïde), <em>Vibrio cholerae</em> (choléra), <em>E. coli</em>, <em><span class=\"nc-purple_bg\">Shigella</span></em>, <em>Campylobacter</em>, <em>Yersinia</em>.</li><li><strong>Virus</strong> : hépatites A et E, rotavirus, <span class=\"nc-purple_bg\">norovirus</span>.</li><li><strong>Parasites</strong> : amœbose, cryptosporidiose, giardiose.</li><li><strong>ATNC</strong> : prions.</li></ul><p>Il faut retenir que la <strong>diarrhée</strong> est une conséquence fréquente des pathologies hydriques et constitue la <strong>2<sup>e</sup> cause de mortalité de l'enfant de moins de 5 ans</strong>.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Les prions concernent notamment des risques alimentaires et iatrogènes ; ne pas les présenter comme un agent usuel de diarrhée transmise par l’eau de boisson. Les rangs mondiaux de mortalité doivent être accompagnés de leur année.</li></ul></div></div>"},{"i":"ef335839ccbd","n":179,"o":"179-3","u":"Définition","t":"Savoir préciser les principaux risques liés à la consommation d’eau","q":"Quels sont les principaux types de risques sanitaires généraux liés à l'eau et à l'alimentation ?","a":"<div class=\"notion-course\"><p>On distingue quatre principaux types de risques sanitaires généraux :</p><ul><li><strong>Biologiques</strong> : bactériens, viraux, parasitaires, fongiques, ATNC (Agents Transmissibles Non Conventionnels comme les prions).</li><li><strong>Physiques</strong> : <span class=\"nc-red_bg\">noyades</span>, brûlures, radioactivité, phénomènes naturels.</li><li><strong>Chimiques</strong> : nitrates, métaux lourds, pesticides, additifs.</li><li><strong>Autres</strong> : allergies, troubles nutritifs, réservoir de vecteurs.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Les prions concernent notamment des risques alimentaires et iatrogènes ; ne pas les présenter comme un agent usuel de diarrhée transmise par l’eau de boisson. Les rangs mondiaux de mortalité doivent être accompagnés de leur année.</li></ul></div></div>"},{"i":"05825a41be8b","n":179,"o":"179-5","u":"Définition","t":"Connaître les mesures de prévention des risques sanitaires liés à l’eau","q":"Quel organisme est responsable de la surveillance de la qualité de l'eau en France ?","a":"<div class=\"notion-course\"><ul><li>Le contrôle sanitaire relève des autorités sanitaires avec <span class=\"nc-yellow_bg\">laboratoires agréés</span> ; le responsable de distribution assure aussi sa surveillance. Respecter les alertes et consignes locales.</li></ul></div>"},{"i":"598bcbfc28d3","n":179,"o":"179-5","u":"Définition","t":"Connaître les mesures de prévention des risques sanitaires liés à l’eau","q":"Comment l'eau destinée à la consommation humaine est-elle définie comme potable selon les critères microbiologiques ?","a":"<div class=\"notion-course\"><ul><li>Respect des limites et références réglementaires ; notamment absence d’E. coli et d’entérocoques intestinaux dans le volume réglementaire de 100 mL. D’autres indicateurs font l’objet de contrôles selon contexte ; ne pas confondre tous les indicateurs avec ces deux limites de qualité.</li></ul></div>"},{"i":"a8640f43faa8","n":179,"o":"179-5","u":"Définition","t":"Connaître les mesures de prévention des risques sanitaires liés à l’eau","q":"Quels sont les trois axes prioritaires de prévention des risques sanitaires liés à l'eau potable ?","a":"<div class=\"notion-course\"><ul><li>Prévenir contamination des captages et réseaux, traiter et contrôler l’eau, assurer assainissement et surveillance. Les exigences chimiques sont des concentrations limites, pas une absence absolue de toute molécule.</li><li>Le contrôle sanitaire relève des autorités sanitaires avec <span class=\"nc-yellow_bg\">laboratoires agréés</span> ; le responsable de distribution assure aussi sa surveillance. Respecter les alertes et consignes locales.</li></ul></div>"},{"i":"3c8ab2312b0b","n":179,"o":"179-6","u":"Définition","t":"Savoir préciser les principaux risques liés à l’alimentation","q":"Quels sont les différents types de risques associés à la salubrité alimentaire ?","a":"<div class=\"notion-course\"><p>Les risques associés à la salubrité alimentaire sont :</p><ul><li>Le <strong>risque infectieux</strong> : conventionnel (<strong>bactérien, parasitaire, fongique, viral, toxinique</strong>) ou non conventionnel (<strong>prion</strong>).</li><li>Le <strong>risque chimique</strong> : lié aux additifs, polluants, antibiotiques, toxiques.</li><li>Le <strong>risque physique</strong> : lié à la radioactivité.</li></ul></div>"},{"i":"6320a0618f69","n":179,"o":"179-6","u":"Définition","t":"Savoir préciser les principaux risques liés à l’alimentation","q":"Quels sont les deux principaux types de risques sanitaires liés à l'alimentation selon l'objectif Rank A ?","a":"<div class=\"notion-course\"><p>Les deux principaux types de risques sanitaires alimentaires sont :</p><ul><li>Les risques liés à la <strong>nutrition</strong>.</li><li>Les risques liés à la <strong>salubrité alimentaire</strong>.</li></ul></div>"},{"i":"df753cf6edac","n":179,"o":"179-6","u":"Définition","t":"Savoir préciser les principaux risques liés à l’alimentation","q":"Quels sont les exemples de troubles nutritifs associés aux risques liés à la nutrition selon l'objectif Rank A ?","a":"<div class=\"notion-course\"><p>Les troubles nutritifs mentionnés sont :</p><ul><li>L'<strong>obésité</strong>.</li><li>L'<strong>anorexie</strong>.</li><li>Les <strong>allergies alimentaires</strong>.</li></ul></div>"},{"i":"6aa3f76560b1","n":179,"o":"179-7","u":"Définition","t":"Savoir définir une toxi-infection alimentaire collective (TIAC) et connaître les différentes symptomatologies de TIAC","q":"Quelle est la définition d'une toxi-infection alimentaire collective (TIAC) ?","a":"<div class=\"notion-course\"><p>Une toxi-infection alimentaire collective (TIAC) se définit par l'apparition d'au moins <strong>deux cas</strong> d'une symptomatologie, en général digestive, dont on peut rapporter la cause à une <strong><span class=\"nc-yellow_bg\">même origine alimentaire</span></strong>. C'est une <strong><span class=\"nc-red nc-bold\">maladie à déclaration obligatoire</span> (MDO)</strong>.</p></div>"},{"i":"b359e715db06","n":179,"o":"179-7","u":"Définition","t":"Savoir définir une toxi-infection alimentaire collective (TIAC) et connaître les différentes symptomatologies de TIAC","q":"Citez les principales symptomatologies cliniques des TIAC et les agents pathogènes associés.","a":"<div class=\"notion-course\"><p>Les principales symptomatologies cliniques des TIAC sont :</p><ul><li><strong>Entéro-toxinogène (cholériforme)</strong> : diarrhée liquide abondante + <span class=\"nc-blue_bg\">vomissements</span> + <span class=\"nc-blue_bg\">absence de fièvre</span>. Incubation <span class=\"nc-pink nc-bold\">courte</span> (quelques <span class=\"nc-pink nc-bold\">heures</span>). Germes associés : <strong><span class=\"nc-purple_bg\">Norovirus</span>, C. perfringens, <span class=\"nc-purple_bg\">B. cereus</span>, <span class=\"nc-purple_bg\">E. coli entérotoxinogène</span></strong>.</li><li><strong>Entéro-invasif (dysentérique)</strong> : <span class=\"nc-red_bg\">fièvre</span> + <span class=\"nc-red_bg\">diarrhée afécale glairosanglante</span> + <span class=\"nc-red_bg\">douleurs abdominales</span>. Incubation <span class=\"nc-pink nc-bold\">longue</span> (24 à 72 h). Germes associés : <strong><span class=\"nc-purple_bg\">Salmonella</span>, <span class=\"nc-purple_bg\">Campylobacter jejuni</span>, <span class=\"nc-purple_bg\">Vibrio parahaemolyticus</span>, <span class=\"nc-purple_bg\">E. coli entéro-invasif,</span> Yersinia, <span class=\"nc-purple_bg\">Shigella</span></strong>.</li><li><strong>Hépatite aiguë</strong> : tableau d'hépatite virale aiguë. Agents associés : <strong>VHA, VHE</strong>.</li><li><strong>Expression extradigestive / neurologique</strong> : manifestations cutanées (érythème, bouffées vasomotrices) ou neurologiques (botulisme : diplopie, paralysie flasque descendante). Agents associés : <strong>C. botulinum, <span class=\"nc-purple_bg\">neurotoxines de dinoflagellés</span>, <span class=\"nc-pink_bg\">histamine</span></strong> (poisson avarié).</li></ul></div>"},{"i":"e43d58f35762","n":179,"o":"179-7","u":"Définition","t":"Savoir définir une toxi-infection alimentaire collective (TIAC) et connaître les différentes symptomatologies de TIAC","q":"Quelles sont les principales causes des TIAC ?","a":"<div class=\"notion-course\"><p>Les causes des TIAC sont la consommation d'aliments contaminés soit par :</p><ul><li>Des <strong>bactéries, virus ou parasites</strong>.</li><li>Des <strong>toxines bactériennes</strong> (produites soit dans l'aliment avant ingestion, soit dans la lumière digestive après ingestion).</li></ul></div>"},{"i":"0f8b2ecea641","n":179,"o":"179-8","u":"Étiologies","t":"Connaître les agents pathogènes responsable de TIAC","q":"Quels sont les agents entéro-toxinogènes responsables de TIAC et leurs caractéristiques cliniques?","a":"<div class=\"notion-course\"><p>Les agents entéro-toxinogènes responsables de TIAC, agissant par toxine préformée, se caractérisent par une incubation plutôt <span class=\"nc-pink nc-bold\">courte</span> et <strong>l'<span class=\"nc-blue_bg\">absence de fièvre</span></strong>. Il s'agit de :</p><ul><li><strong><span class=\"nc-purple_bg\">Staphylococcus aureus</span></strong> (2 à 4 h) : <span class=\"nc-blue_bg\">vomissements</span>, <span class=\"nc-red_bg\">douleurs abdominales</span>, diarrhée.</li><li><strong><span class=\"nc-purple_bg\">Clostridium perfringens</span></strong> (8 à 24 h) : diarrhée aiguë, <span class=\"nc-blue_bg\">absence de fièvre</span>.</li><li><strong><span class=\"nc-purple_bg\">Bacillus cereus</span></strong>.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Botulisme suspect : urgence spécialisée et discussion précoce de l’antitoxine, sans attendre une insuffisance respiratoire. STEC/EHEC : surveiller SHU ; éviter ralentisseurs du transit et antibiothérapie systématique, qui peut être délétère. Les durées d’incubation se recouvrent et ne prouvent pas à elles seules l’agent.</li></ul></div></div>"},{"i":"1a2ec63f16dd","n":179,"o":"179-8","u":"Étiologies","t":"Connaître les agents pathogènes responsable de TIAC","q":"Quelles sont les spécificités de la TIAC à E. coli entérohémorragique (O157:H7) chez l'enfant?","a":"<div class=\"notion-course\"><p>La TIAC à <strong>E. coli entérohémorragique (O157:H7)</strong> est une urgence, particulièrement chez l'enfant de <strong>moins de 5 ans</strong>, étant la <strong>première cause d'insuffisance rénale aiguë organique avant 3 ans</strong>. Elle évolue en 3 phases :</p><ul><li>Phase digestive : <strong>diarrhée sanglante</strong>.</li><li>Phase hématologique : <strong>microangiopathie thrombotique</strong> (anémie hémolytique, thrombopénie).</li><li>Phase rénale : <strong>insuffisance rénale aiguë oligo-anurique</strong>, nécessitant une dialyse dans 50% des cas.</li></ul><p>La prévention repose sur l'interdiction des laitages non pasteurisés et des viandes crues avant 5 ans.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Botulisme suspect : urgence spécialisée et discussion précoce de l’antitoxine, sans attendre une insuffisance respiratoire. STEC/EHEC : surveiller SHU ; éviter ralentisseurs du transit et antibiothérapie systématique, qui peut être délétère. Les durées d’incubation se recouvrent et ne prouvent pas à elles seules l’agent.</li></ul></div></div>"},{"i":"2fecc3a3f7c6","n":179,"o":"179-8","u":"Étiologies","t":"Connaître les agents pathogènes responsable de TIAC","q":"Quels sont les agents entéro-invasifs responsables de TIAC et leurs caractéristiques cliniques?","a":"<div class=\"notion-course\"><p>Les agents entéro-invasifs responsables de TIAC, avec une incubation plus <span class=\"nc-pink nc-bold\">longue</span> et potentiellement une <span class=\"nc-red_bg\">fièvre</span>, sont :</p><ul><li><strong><span class=\"nc-purple_bg\">Salmonella</span> enterica non typhi</strong> (12 à 24 h) : diarrhée aiguë fébrile.</li><li><strong>Shigella</strong>.</li><li><strong><span class=\"nc-purple_bg\">Campylobacter jejuni</span></strong>.</li><li><strong><span class=\"nc-purple_bg\">Yersinia enterocolitica</span></strong>.</li><li><strong>Listeria</strong>.</li></ul><p>Ils se manifestent généralement par une <strong>diarrhée glairo-sanglante</strong> avec de la <span class=\"nc-red_bg\">fièvre</span>.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Botulisme suspect : urgence spécialisée et discussion précoce de l’antitoxine, sans attendre une insuffisance respiratoire. STEC/EHEC : surveiller SHU ; éviter ralentisseurs du transit et antibiothérapie systématique, qui peut être délétère. Les durées d’incubation se recouvrent et ne prouvent pas à elles seules l’agent.</li></ul></div></div>"},{"i":"355267eee232","n":179,"o":"179-8","u":"Étiologies","t":"Connaître les agents pathogènes responsable de TIAC","q":"Quelle est la présentation clinique caractéristique du botulisme lors d'une TIAC due à Clostridium botulinum?","a":"<div class=\"notion-course\"><p>Le botulisme, causé par <strong><span class=\"nc-purple_bg\">Clostridium botulinum</span></strong> après une incubation de <strong>12 à 72 <span class=\"nc-pink nc-bold\">heures</span></strong>, se caractérise par :</p><ul><li>Un <strong><span class=\"nc-red_bg\">syndrome parasympathicolytique</span></strong> : mydriase, sécheresse buccale, dysphagie, constipation, dysurie.</li><li>Une <strong><span class=\"nc-red_bg\">paralysie descendante</span></strong>.</li></ul><p>Il est crucial de noter <strong>l'<span class=\"nc-blue_bg\">absence de fièvre</span></strong>, une vigilance normale et l'absence de syndrome méningé. Une <strong><span class=\"nc-pink_bg\">réanimation</span></strong> et une <strong><span class=\"nc-pink_bg\">sérothérapie</span></strong> sont indiquées en cas d'<span class=\"nc-red nc-bold\">atteinte respiratoire</span>.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Botulisme suspect : urgence spécialisée et discussion précoce de l’antitoxine, sans attendre une insuffisance respiratoire. STEC/EHEC : surveiller SHU ; éviter ralentisseurs du transit et antibiothérapie systématique, qui peut être délétère. Les durées d’incubation se recouvrent et ne prouvent pas à elles seules l’agent.</li></ul></div></div>"},{"i":"dec9f4a36a66","n":179,"o":"179-8","u":"Étiologies","t":"Connaître les agents pathogènes responsable de TIAC","q":"Quels agents pathogènes de TIAC ont une incubation courte (inférieure à 6 heures) et sont plutôt caractérisés par des vomissements?","a":"<div class=\"notion-course\"><p>Un agent typique de cette catégorie est <strong><span class=\"nc-purple_bg\">Staphylococcus aureus</span></strong>, avec une incubation de <strong>2 à 4 <span class=\"nc-pink nc-bold\">heures</span></strong>, provoquant <strong><span class=\"nc-blue_bg\">vomissements</span></strong>, <span class=\"nc-red_bg\">douleurs abdominales</span> et diarrhée, généralement sans <span class=\"nc-red_bg\">fièvre</span>. L'intoxication histaminique, bien que non infectieuse, a une incubation encore plus <span class=\"nc-pink nc-bold\">courte</span> (<strong>10 min à 1h</strong>) avec <span class=\"nc-blue_bg\">troubles vasomoteurs</span>, <span class=\"nc-blue_bg\">céphalées</span> et <span class=\"nc-blue_bg\">troubles digestifs</span>.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Botulisme suspect : urgence spécialisée et discussion précoce de l’antitoxine, sans attendre une insuffisance respiratoire. STEC/EHEC : surveiller SHU ; éviter ralentisseurs du transit et antibiothérapie systématique, qui peut être délétère. Les durées d’incubation se recouvrent et ne prouvent pas à elles seules l’agent.</li></ul></div></div>"},{"i":"06992f6c26f2","n":179,"o":"179-9","u":"Définition","t":"Connaître les modalités de détection et de signalement d’une suspicion de TIAC","q":"Quelle est la différence fondamentale entre le 'signalement' et la 'notification' d'une TIAC, un piège classique ?","a":"<div class=\"notion-course\">Le piège classique est de confondre le signalement et la notification :<ul><li>Le <strong>signalement</strong> est une procédure d'<strong>urgence</strong>, immédiate, réalisée par tout moyen.</li><li>La <strong>notification</strong> est <strong>différée</strong> et s'effectue sur un formulaire dédié à l'ARS.</li></ul></div>"},{"i":"6c7fb2d14f71","n":179,"o":"179-9","u":"Définition","t":"Connaître les modalités de détection et de signalement d’une suspicion de TIAC","q":"Après le signalement initial d'une TIAC, quelle est la procédure complémentaire à effectuer et quelle mesure pratique doit être prise concernant les repas ?","a":"<div class=\"notion-course\">Après le signalement initial, il faut :<ul><li>Procéder à la <strong>notification de la déclaration</strong> via un formulaire dédié à l'ARS.</li><li><strong>Conserver tous les restes des derniers repas à 4 °C</strong> pour les mettre à disposition de la <span class=\"nc-yellow_bg\">DDPP</span>.</li></ul></div>"},{"i":"9ee817b344be","n":179,"o":"179-9","u":"Définition","t":"Connaître les modalités de détection et de signalement d’une suspicion de TIAC","q":"À qui doit-on signaler sans délai une suspicion de TIAC et par quel moyen ?","a":"<div class=\"notion-course\">Le signalement d'une suspicion de TIAC doit être fait <strong>sans délai et par tout moyen approprié</strong> (téléphone, fax) :<ul><li>Au <strong>médecin de l'<span class=\"nc-red nc-bold\">ARS</span></strong> (Agence Régionale de Santé).</li><li>À la <strong><span class=\"nc-blue_bg\">DDPP</span></strong><span class=\"nc-blue_bg\"> (Direction Départementale de la Protection des Populations)</span>.</li></ul></div>"},{"i":"f3200b05b2c9","n":179,"o":"179-9","u":"Définition","t":"Connaître les modalités de détection et de signalement d’une suspicion de TIAC","q":"Quels sont les trois éléments à réunir pour détecter une suspicion de TIAC (Toxi-Infection Alimentaire Collective) ?","a":"<div class=\"notion-course\">Pour détecter une suspicion de TIAC, il faut réunir :<ul><li>Une <strong>symptomatologie compatible</strong> (digestive ± extradigestive).</li><li>Au moins <strong>2 cas groupés</strong> dans le temps et l'espace.</li><li>Une <strong><span class=\"nc-blue_bg\">origine alimentaire commune</span></strong>.</li></ul></div>"},{"i":"8e1e179279c6","n":179,"o":"179-1","u":"Étiologies","t":"Connaître les parasitoses transmises par la consommation d’eau","q":"Quels sont les points essentiels concernant les parasitoses transmises par la consommation d’eau ?","a":"<div class=\"notion-course\"><p><span>Les</span> parasitoses transmises par la <span>consommation d'eau</span> sont quasi exclusivement des <strong><span>protozooses</span></strong>, à transmission <span>féco-orale</span>. Quatre agents sont à connaître.</p>\n      <table>\n        <thead><tr><th>Parasitose</th><th>Agent &amp; réservoir</th><th>Clinique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Amoebose</span></strong></td>\n            <td><span>Entamoeba histolytica</span> ; protozoose à réservoir <strong>strictement humain</strong>, cosmopolite</td>\n            <td>Surtout dans <span>les</span> zones à <span>hygiène pauvre</span> ; amoebose intestinale</td>\n          </tr>\n          <tr>\n            <td><strong><span>Cryptosporidiose</span></strong></td>\n            <td><span>Cryptosporidium</span> ; protozoose cosmopolite ; transmission <span>féco-orale</span> ou <span>manu-portée</span></td>\n            <td><span>Diarrhée aiguë cholérigorme</span> ou <span>chronique</span> + <span>malabsorption</span> chez l'<span>immunodéprimé</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Giardiose</span></strong></td>\n            <td>Giardia intestinalis peut infecter l’humain et d’autres mammifères ; une transmission zoonotique est possible selon les assemblages. Eau, aliments et transmission féco-orale interhumaine sont à considérer.</td>\n            <td>Souvent <span>asymptomatique</span> ; possible <span>diarrhée chronique</span> de l'enfant → <span>malabsorption / malnutrition</span> (pays pauvres)</td>\n          </tr>\n          <tr>\n            <td><strong><span>Toxoplasmose</span></strong></td>\n            <td><span>Toxoplasma gondii</span> ; protozoose cosmopolite dont le <strong>chat est l'hôte définitif</strong></td>\n            <td>Symptomatique dans <span>≈ 20 %</span> des cas, tableau aspécifique (<span><span class=\"nc-red_bg\">fièvre</span></span>, <span>polyadénopathies</span>…)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 172 — Parasitose digestive · 175 — Voyage en pays tropical</em></p></div>"},{"i":"23c272aa87f4","n":179,"o":"179-2","u":"Étiologies","t":"Connaître les parasitoses transmises par les aliments","q":"Quels sont les points essentiels concernant les parasitoses transmises par les aliments ?","a":"<div class=\"notion-course\"><p><span>Les</span> parasitoses d'origine <span>alimentaire</span> sont surtout des <strong><span>helminthoses</span></strong>, acquises en ingérant viande ou poisson <span>crus ou insuffisamment cuits</span>.</p>\n      <table>\n        <thead><tr><th>Parasitose</th><th>Mode de contamination</th><th>Clinique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Taeniasis</span></strong></td>\n            <td>Ingestion de viande parasitée (bœuf, porc)</td>\n            <td>Téniasis intestinal — <em>détaillé à l'item 172</em></td>\n          </tr>\n          <tr>\n            <td><strong><span>Trichinellose</span></strong></td>\n            <td>Zoonose cosmopolite ; l'homme est un <strong>hôte accidentel</strong> en mangeant de la <span>viande crue ou peu cuite</span> contenant des <span>larves enkystées</span> → migration vers <span>les</span> <span>muscles striés</span></td>\n            <td><span>Polymyosite fébrile</span> + <span>œdème de la face</span> ; <span>évolution grave voire mortelle</span> à la phase précoce de dissémination larvaire</td>\n          </tr>\n          <tr>\n            <td><strong><span>Anisakiase</span></strong></td>\n            <td>Zoonose des <strong>mers froides</strong> ; ingestion de <span>poisson infesté de larves</span> (cru, mariné ou mal cuit)</td>\n            <td>Symptômes digestifs précoces (<span>gastralgies</span>, <span>nausées</span>, <span>vomissements</span>) ± <span>réactions allergiques</span> intestinales ou généralisées</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 172 — Parasitose digestive · 173 — Zoonose</em></p></div>"},{"i":"50781012394e","n":179,"o":"179-4","u":"Définition","t":"Savoir préciser les sources de pollution de l’eau","q":"Quels sont les points essentiels concernant préciser les sources de pollution de l’eau ?","a":"<div class=\"notion-course\"><p>La <span>pollution de l'eau</span> provient de trois sources principales, selon l'activité humaine en cause.</p>\n      <table>\n        <thead><tr><th>Source</th><th>Origine</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">Pollution domestique</span></span></strong></td>\n            <td>Liée à l'<strong>utilisation quotidienne de l'eau au domicile</strong> : eaux de toilettes et de lavage contenant détergents, produits ménagers, graisses et résidus</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">Pollution agricole</span></span></strong></td>\n            <td>Liée à l'<strong>exploitation agricole intensive</strong> (élevage et cultures végétales) : déchets physiologiques de l'élevage, engrais, herbicides, <span>pesticides</span></td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">Pollution industrielle</span></span></strong></td>\n            <td>Liée aux <strong>rejets de tous types d'industries</strong> : effluents industriels, chauffage, stagnation de l'eau, hôpitaux</td>\n          </tr>\n        </tbody>\n      </table></div>"},{"i":"62fc593da3b8","n":179,"o":"179-10","u":"Définition","t":"Connaître les différentes étapes d’une investigation de TIAC","q":"Quels sont les points essentiels concernant les différentes étapes d’une investigation de TIAC ?","a":"<div class=\"notion-course\"><ul><li>Définir les <span class=\"nc-blue_bg\">cas</span>, recenser malades et personnes exposées non malades, décrire dates/symptômes et recueillir les aliments consommés. Conserver restes et plats témoins dans les conditions demandées par les enquêteurs.</li><li>Enquête clinique et épidémiologique, enquête alimentaire et enquête sanitaire sont coordonnées ; prélèvements chez les patients et dans les aliments orientés par les hypothèses.</li><li>Cohorte rétrospective si la population exposée est bien définie et accessible ; cas-témoins si elle ne l’est pas. Le choix ne dépend pas d’un seuil rigide de trente personnes.</li><li>Comparer taux d’attaque, risques relatifs ou odds ratios avec leurs incertitudes et biais. Une valeur supérieure à un ne suffit pas, seule, à prouver l’aliment responsable.</li><li>Prendre les mesures de contrôle dès qu’indiquées puis produire un bilan ; les investigations ne doivent pas retarder la maîtrise de l’exposition.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d941817cab29f30990d5cf4d?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
